using System;using System.IO;using System.Text;using System.ComponentModel;using System.Runtime.Serialization;
namespace CircuitoStudio {
[DataContract]public sealed class CalculationProfile {
[DataMember]public string Engine{get;set;}[DataMember]public string Standard{get;set;}[DataMember]public string Edition{get;set;}[DataMember]public string ReferenceSource{get;set;}[DataMember]public string Assumptions{get;set;}
public CalculationProfile(){Engine=CalculationManifest.EngineId;Standard=Edition=ReferenceSource=Assumptions="";}
public CalculationProfile Copy(){return (CalculationProfile)MemberwiseClone();}
public void Validate(){if(Engine!=CalculationManifest.EngineId)throw new InvalidDataException("Revisão do motor de cálculo incompatível: "+Engine+". Abra em versão correspondente ou faça uma migração explícita revisada.");foreach(string text in new[]{Standard,Edition,ReferenceSource,Assumptions})if(text==null||text.Length>10000||text.IndexOf('\0')>=0)throw new InvalidDataException("Referência/hipóteses inválidas (até 10000 caracteres).");bool any=!String.IsNullOrWhiteSpace(Standard+Edition+ReferenceSource);if(any&&(String.IsNullOrWhiteSpace(Standard)||String.IsNullOrWhiteSpace(Edition)||String.IsNullOrWhiteSpace(ReferenceSource)))throw new InvalidDataException("Para declarar uma referência, informe norma, edição e fonte. Ou deixe os três campos vazios.");}
}
public sealed partial class Project{[DataMember(Order=95),Browsable(false)]public CalculationProfile CalculationProfile{get;set;}}
public static class CalculationManifest {
public const string EngineId="cs-modelos-0.2.20261024.1";
public static void Apply(Project project,CalculationProfile profile){if(project==null||profile==null)throw new InvalidDataException("Projeto/perfil ausente.");profile.Validate();project.CalculationProfile=profile.Copy();}
public static string Describe(Project project){var text=new StringBuilder();text.AppendLine("REVISÃO DO MOTOR: "+EngineId);var profile=project.CalculationProfile;if(profile==null)text.AppendLine("Perfil não registrado neste projeto legado. Os resultados usam a revisão atual acima; salve o perfil para vincular a revisão ao arquivo.");else{profile.Validate();text.AppendLine("Revisão vinculada ao projeto: "+profile.Engine);text.AppendLine("Referência declarada: "+(String.IsNullOrWhiteSpace(profile.Standard)?"Não definida":profile.Standard+"; edição "+profile.Edition+"; fonte "+profile.ReferenceSource));text.AppendLine("Hipóteses adicionais do projetista: "+(String.IsNullOrWhiteSpace(profile.Assumptions)?"Não informadas":profile.Assumptions));}
text.AppendLine("Norma/edição são referências declaradas pelo projetista. Não ativam uma implementação normativa nem substituem as hipóteses e limites dos módulos. Alterar textos não altera os algoritmos.");
text.AppendLine("MÓDULOS E UNIDADES — revisão 1 de cada método:");text.AppendLine("cargas-pq-v1: rede radial; P/Q senoidais, kW/kvar/kVA, demanda terminal; alimentadores agregam sem dupla contagem; fases por fasores em tensão nominal. Sem harmônicos ou fluxo de potência com perdas.");text.AppendLine("queda-linear-v1: Rcosφ+Xsinφ, R/X em ohm/km, comprimento em m convertido em km; soma acumulada na mesma base de tensão; limite absoluto global/próprio. Não resolve desequilíbrio real de tensão.");text.AppendLine("ampacidade-fatores-v1: Iz de tabela × Ft × Fg × paralelos, fontes e condições declaradas; incompatibilidade de snapshot impede reutilização. Sem tabela normativa embutida.");text.AppendLine("curto-inicial-sequencias-v1: Ik 3F=cU/(sqrt(3)|Z|), 2F com Z2=Z1; ohm, V, saída kA. Nominal aproximado, sem extremos normativos nem contribuição de motores. Laços TT/TN por Zs total declarado somente nos circuitos suportados.");
switch(project.Source.Model){case SourceModel.GeradorSincrono:text.AppendLine("fonte-gerador-v1: impedância inicial Xd'' percentual na base U²/S e R declarada; corrente simétrica inicial. Não aplica onda R-L estacionária nem calcula decremento do gerador.");break;case SourceModel.UPS:text.AppendLine("fonte-ups-v1: inversor limitado por corrente declarada, sem U/Z ou aprovação de laços; bypass é cenário de rede separado, sem transferência automática.");break;case SourceModel.ImpedanciaDefinida:text.AppendLine("fonte-rx-v1: impedâncias R/X declaradas; neutro/PE desconhecido permanece distinto de zero. Só usa sequências e tipos de falta suportados.");break;default:text.AppendLine("fonte-rede-v1: equivalente por Icc/RX e transformador opcional uk/perdas; conferir ponto de Icc para não duplicar transformador.");break;}
text.AppendLine("partida-linear-v1: corrente/FP de partida trifásica declarados, fonte e percurso conhecidos, substituição da carga normal do motor. Sem aceleração, torque ou aquecimento dinâmico.");text.AppendLine("adiabatico-v1: S=sqrt(I²t)/k; PVC/XLPE Cu/Al, 0<t≤5 s, um paralelo; k e temperaturas nos detalhes do circuito. Curvas/I²t do fabricante necessários.");text.AppendLine("protecao-nominal-v1: Ib/In/Iz/I2 e capacidade contra Ik nominal; polos/tensão/frequência/Icu-Icn na condição exata vinculada. Tempo de seccionamento, seletividade e backup não são presumidos.");text.AppendLine("DINÂMICA R-L: fonte de tensão com R/X constantes e frequência declarada; picos/onda nesse modelo não incluem a evolução eletromecânica de máquinas. Fontes incompatíveis conservam resultado pendente.");text.AppendLine("Precisão: IEEE-754 double; nenhuma quantização intermediária de entrada; apresentação pode arredondar. Dados persistidos com serializer JSON .NET. Ausências seguem os contratos dos campos: opcionais nulos e zeros documentados são indeterminados, não aprovações.");text.AppendLine("AVISOS: não é certificação normativa. Verificar condições, dados do fabricante, método e edição aplicáveis. Funções sem modelo/dados permanecem pendentes. Referências de proteção não comprovam coordenação ou Ik máximo.");return text.ToString();}
}
}
